use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// The hosts this node's HTTPClient handle is scoped to. A request outside the
/// allowlist traps at the boundary, which would fail the whole tick, so a URL
/// whose host is not one of these is reported as a failure and never requested.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

struct Node;

fn strip_prefix_ci<'a>(s: &'a str, prefix: &str) -> Option<&'a str> {
    let head = s.get(..prefix.len())?;
    if head.eq_ignore_ascii_case(prefix) {
        s.get(prefix.len()..)
    } else {
        None
    }
}

/// Extract the lowercase host of an http(s) URL, conservatively. Anything
/// unusual (userinfo, backslashes, whitespace, control characters, a
/// non-numeric port) is rejected rather than guessed at.
fn host_of(url: &str) -> Result<String, &'static str> {
    if url.chars().any(|c| c.is_whitespace() || c.is_control()) {
        return Err("url contains whitespace or control characters");
    }
    let rest = strip_prefix_ci(url, "https://")
        .or_else(|| strip_prefix_ci(url, "http://"))
        .ok_or("url scheme is not http or https")?;
    let authority = rest
        .split(|c| c == '/' || c == '?' || c == '#')
        .next()
        .unwrap_or("");
    if authority.is_empty() {
        return Err("url has no host");
    }
    if authority.contains('@') || authority.contains('\\') {
        return Err("url authority is malformed");
    }
    let host = match authority.rsplit_once(':') {
        Some((h, p)) => {
            if p.chars().all(|c| c.is_ascii_digit()) {
                h
            } else {
                return Err("url port is malformed");
            }
        }
        None => authority,
    };
    if host.is_empty() {
        return Err("url has no host");
    }
    Ok(host.to_ascii_lowercase())
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();
        let mut seen: Vec<String> = Vec::new();

        for raw in subscriptions.urls {
            let url = raw.trim();
            if url.is_empty() {
                continue;
            }
            if seen.iter().any(|s| s == url) {
                continue;
            }
            seen.push(url.to_string());

            let host = match host_of(url) {
                Ok(h) => h,
                Err(e) => {
                    failures.push(FetchFailure {
                        url: url.to_string(),
                        error: e.to_string(),
                    });
                    continue;
                }
            };

            if !ALLOWED_HOSTS.iter().any(|a| *a == host) {
                failures.push(FetchFailure {
                    url: url.to_string(),
                    error: "host is outside this node's allowlist; not requested".to_string(),
                });
                continue;
            }

            match http_client::fetch(url) {
                Ok(body) => documents.push(FeedDocument {
                    url: url.to_string(),
                    body,
                }),
                Err(error) => failures.push(FetchFailure {
                    url: url.to_string(),
                    error,
                }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
